CREATE OR REPLACE FUNCTION public.consume_rate_limit(p_namespace text, p_operation text, p_subject uuid)
 RETURNS TABLE(allowed boolean, remaining integer, retry_after_seconds integer, reset_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '2s'
 SET statement_timeout TO '3s'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_policies text[];
  v_limits integer[];
  v_seconds integer[];
  v_starts timestamptz[] := '{}';
  v_ends timestamptz[] := '{}';
  v_counts integer[] := '{}';
  v_count integer;
  v_i integer;
begin
  -- SECURITY DEFINER must not make this a public quota-admission API.
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service role required' using errcode = '42501';
  end if;
  if p_namespace is null or p_namespace not in ('tse:production', 'tse:preview', 'tse:local')
     or p_subject is null then
    raise exception 'Invalid rate limit subject or namespace' using errcode = '22023';
  end if;

  -- Keep shared budgets in the same lock order for every operation. Callers
  -- cannot select limits, window sizes, SQL identifiers, or individual budgets.
  case p_operation
    when 'checkout' then
      v_policies := array['checkout-minute', 'checkout-hour'];
      v_limits := array[5, 30];
      v_seconds := array[60, 3600];
    when 'upload' then
      v_policies := array['upload-minute', 'upload-day'];
      v_limits := array[20, 200];
      v_seconds := array[60, 86400];
    when 'server-upload' then
      v_policies := array['upload-minute', 'upload-day', 'server-upload-minute'];
      v_limits := array[20, 200, 10];
      v_seconds := array[60, 86400, 60];
    else
      raise exception 'Invalid rate limit operation' using errcode = '22023';
  end case;

  allowed := true;
  remaining := 2147483647;
  retry_after_seconds := 0;
  reset_at := null;

  for v_i in 1..array_length(v_policies, 1) loop
    v_starts[v_i] := to_timestamp(floor(extract(epoch from v_now) / v_seconds[v_i]) * v_seconds[v_i]);
    v_ends[v_i] := v_starts[v_i] + make_interval(secs => v_seconds[v_i]);

    insert into rate_limit_private.counters (namespace, policy, subject_key, window_start, window_end)
    values (p_namespace, v_policies[v_i], p_subject, v_starts[v_i], v_ends[v_i])
    on conflict (namespace, subject_key, policy, window_start) do nothing;

    -- The unique key serializes first creation; row locks serialize admission.
    -- All locks are held through the later increments until the RPC commits.
    select c.request_count into strict v_count
    from rate_limit_private.counters c
    where c.namespace = p_namespace and c.subject_key = p_subject
      and c.policy = v_policies[v_i] and c.window_start = v_starts[v_i]
    for update;
    v_counts[v_i] := v_count;

    if v_count >= v_limits[v_i] then
      allowed := false;
      retry_after_seconds := greatest(retry_after_seconds,
        ceil(extract(epoch from (v_ends[v_i] - v_now)))::integer);
      reset_at := greatest(reset_at, v_ends[v_i]);
    end if;
  end loop;

  -- All-or-nothing across budgets: a denied request consumes none of them.
  for v_i in 1..array_length(v_policies, 1) loop
    if allowed then
      update rate_limit_private.counters c set request_count = c.request_count + 1
      where c.namespace = p_namespace and c.subject_key = p_subject
        and c.policy = v_policies[v_i] and c.window_start = v_starts[v_i];
      v_counts[v_i] := v_counts[v_i] + 1;
      reset_at := least(reset_at, v_ends[v_i]);
    end if;
    remaining := least(remaining, greatest(0, v_limits[v_i] - v_counts[v_i]));
  end loop;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_track_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  rights_total numeric(7,2);
begin
  -- Service-role operations and verified admins are trusted moderation paths.
  if auth.role() = 'service_role' or public.is_admin() then
    if new.status = 'approved' and (tg_op = 'INSERT' or old.status is distinct from 'approved') then
      select coalesce(sum(ownership_percent), 0)
      into rights_total
      from public.rights_holders
      where track_id = new.id;

      if abs(rights_total - 100) > 0.01 then
        raise exception 'Approved tracks must have rights holder ownership totals equal to 100%%.';
      end if;

      new.approved_at = coalesce(new.approved_at, now());
      new.approved_by = coalesce(new.approved_by, auth.uid());
    end if;

    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.artist_user_id <> auth.uid() then
      raise exception 'Artists may only create their own tracks.';
    end if;

    if new.status not in ('draft', 'pending_review') then
      raise exception 'Artists may only create drafts or submit tracks for review.';
    end if;

    if new.approved_at is not null or new.approved_by is not null then
      raise exception 'Approval fields are managed by admin workflows only.';
    end if;

    if new.featured then
      raise exception 'Featured state is managed by admins.';
    end if;

    return new;
  end if;

  if old.artist_user_id <> auth.uid() then
    raise exception 'Artists may only update their own tracks.';
  end if;

  if new.artist_user_id is distinct from old.artist_user_id then
    raise exception 'Track ownership cannot be changed by artists.';
  end if;

  if new.approved_at is distinct from old.approved_at or new.approved_by is distinct from old.approved_by then
    raise exception 'Approval fields are managed by admin workflows only.';
  end if;

  if new.featured is distinct from old.featured then
    raise exception 'Featured state is managed by admins.';
  end if;

  if old.status = 'approved' then
    if new.status <> 'archived' then
      raise exception 'Approved tracks may only be archived by artists.';
    end if;

    return new;
  end if;

  if new.status not in ('draft', 'pending_review', 'archived') then
    raise exception 'Artists may only save drafts, submit for review, or archive their own tracks.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_user_profile_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  -- Service-role operations and verified admins are trusted role-management paths.
  if auth.role() = 'service_role' or public.is_admin() then
    return new;
  end if;

  if auth.uid() is null then
    raise exception 'Authenticated access is required to manage a profile.';
  end if;

  if new.id <> auth.uid() then
    raise exception 'You may only manage your own profile.';
  end if;

  if tg_op = 'INSERT' and new.role is not null then
    raise exception 'Role assignment is managed by trusted server workflows only.';
  end if;

  if tg_op = 'UPDATE' and new.role is distinct from old.role then
    raise exception 'Role changes are managed by trusted server workflows only.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
